/**
 * Builds the two scripts the view mirror injects (ADR-0039) and writes them,
 * as strings, to `src/workspace/appWindows/mirror/bundles.generated.ts`.
 *
 * The scripts run inside sandboxed documents the workspace assembles as text,
 * so they cannot be ordinary bundle chunks. The generated file is committed;
 * `scripts/app-view-mirror-bundles.test.mjs` fails when it is out of date.
 *
 * Usage: node scripts/build-app-view-mirror.mjs [--check]
 */
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const directory = path.join(root, 'src/workspace/appWindows/mirror');
export const GENERATED_FILE = path.join(directory, 'bundles.generated.ts');

async function bundle(entry) {
	const result = await build({
		entryPoints: [path.join(directory, entry)],
		bundle: true,
		write: false,
		format: 'iife',
		platform: 'browser',
		target: 'es2020',
		minify: true,
		legalComments: 'none',
		charset: 'ascii',
		logLevel: 'silent',
	});
	// The script is placed inside a <script> element of an HTML string.
	return result.outputFiles[0].text.trim().replaceAll('</script', '<\\/script').replaceAll('<!--', '<\\!--');
}

export async function generate() {
	const version = JSON.parse(
		await readFile(path.join(root, 'node_modules/rrweb/package.json'), 'utf8'),
	).version;
	const [recorder, replica] = await Promise.all([bundle('recorderEntry.ts'), bundle('replicaEntry.ts')]);
	return [
		'// Generated by scripts/build-app-view-mirror.mjs. Do not edit.',
		`export const MIRROR_RRWEB_VERSION = ${JSON.stringify(version)};`,
		'/** Runs inside a view: records it while someone is watching. */',
		`export const MIRROR_RECORDER_SCRIPT = ${JSON.stringify(recorder)};`,
		'/** Runs inside a mirror document: redraws the recorded view. */',
		`export const MIRROR_REPLICA_SCRIPT = ${JSON.stringify(replica)};`,
		'',
	].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
	const text = await generate();
	if (process.argv.includes('--check')) {
		const current = await readFile(GENERATED_FILE, 'utf8').catch(() => '');
		if (current !== text) {
			console.error('bundles.generated.ts is out of date; run node scripts/build-app-view-mirror.mjs');
			process.exit(1);
		}
	} else {
		await writeFile(GENERATED_FILE, text);
		console.log(`wrote ${path.relative(root, GENERATED_FILE)} (${text.length} chars)`);
	}
}
